#!/usr/bin/env bash
#
# Deploy TAPat: API on AWS EC2 (+ Tailscale Funnel), web on Vercel. docs/deployment.md §6.4.
# Run from the repo root in Git Bash.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Git Bash rewrites arguments like /aws/service/... and /dev/sda1 for native exes (aws.exe) without this.
export MSYS_NO_PATHCONV=1

# Wizard state: non-secret values plus BASIC_AUTH_PASSWORD. Git-ignored (.gitignore). Git Bash mounts are
# noacl, so a 600 mode isn't enforced on Windows: the clone folder's NTFS ACLs protect it.
STATE_FILE="deploy/.wizard.env"
ENV_FILE="$STATE_FILE"

SSH_KEY="$HOME/.ssh/tapat_aws_ed25519"
KEY_PAIR_NAME=tapat-deploy
SG_NAME=tapat-ssh
INSTANCE_TAG=tapat-api
SSH_USER=ubuntu
UBUNTU_AMI_PARAM=/aws/service/canonical/ubuntu/server/24.04/stable/current/amd64/hvm/ebs-gp3/ami-id
SSH_OPTS=(-i "$SSH_KEY" -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10)

# awsq ARGS… runs aws with text output. aws.exe on Windows ends lines with CRLF: every captured value goes through here.
awsq() { aws "$@" --output text | tr -d '\r'; }

# winpath PATH prints the Windows form of PATH, for file arguments to native exes (aws, gh).
winpath() { if command -v cygpath >/dev/null 2>&1; then cygpath -w "$1"; else printf '%s' "$1"; fi; }

# vm CMD runs CMD on the instance. vm_tty adds a terminal, for commands that print a login URL and wait.
vm()     { ssh "${SSH_OPTS[@]}" "$SSH_USER@$AWS_HOST" "$@"; }
vm_tty() { ssh -t "${SSH_OPTS[@]}" "$SSH_USER@$AWS_HOST" "$@"; }

# http_code URL [curl-args…] prints the HTTP status; 000 when unreachable.
http_code() { local url="$1"; shift; curl -s -o /dev/null -w '%{http_code}' --max-time 20 "$@" "$url" || true; }

# copy_clip VALUE puts VALUE on the clipboard; without a clipboard tool, shows it only if the human agrees.
copy_clip() {
  local copied=1
  if   command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe && copied=0
  elif command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy && copied=0
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard && copied=0
  fi
  if (( copied == 0 )); then
    printf '  %s✓ copied to clipboard%s\n' "$GREEN" "$RESET"
  elif confirm "No clipboard tool found. Show it on screen instead?"; then
    say "$1"
  fi
}

# pass "…" prints a passed check; fail_check NAME DETAIL records a failed one for the closing summary.
pass() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
fail_check() { SKIPPED+=("check failed: $1 — $2"); warn "check failed: $1 — $2"; }

# write_prod KEY VALUE upserts KEY into the prod .env (PROD_ENV_PATH), not the state file. finish only
# reports ENV_FILE, so the key moves from WRITTEN_ENV to PROD_WRITTEN, listed after the summary.
PROD_WRITTEN=()
write_prod() {
  ENV_FILE="$PROD_ENV_PATH"
  write_env "$1" "$2"
  ENV_FILE="$STATE_FILE"
  unset 'WRITTEN_ENV[-1]'
  PROD_WRITTEN+=("$1")
}

run_wizard() {

TOTAL_STAGES=13

banner "TAPat deploy: AWS EC2 API + Vercel web"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
if [[ ! -f deploy/provision.sh ]]; then warn "run from the repo root"; exit 1; fi
for tool in aws gh ssh ssh-keygen curl git; do
  command -v "$tool" >/dev/null 2>&1 || { warn "missing tool: $tool"; exit 1; }
done
if ! ARN=$(awsq sts get-caller-identity --query Arn 2>/dev/null) || [[ -z "$ARN" ]]; then
  open_url "https://console.aws.amazon.com/iam/home#/security_credentials"
  warn "the AWS CLI has no working credentials: run 'aws configure' (or 'aws login'), then re-run"
  exit 1
fi
say "AWS identity: $ARN"
if ! gh auth status >/dev/null 2>&1; then warn "the GitHub CLI is not logged in: run 'gh auth login', then re-run"; exit 1; fi
ask AWS_REGION "AWS region [ap-southeast-1]:"
write_env AWS_REGION "${AWS_REGION:-ap-southeast-1}"
R="$AWS_REGION"
GITHUB_REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner | tr -d '\r')
write_env GITHUB_REPO "$GITHUB_REPO"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Basic-auth credentials"
say "One user + password protects both front doors: Caddy on the Funnel URL and"
say "the Vercel middleware (WEB_BASIC_AUTH). The team and the judges get it."
while :; do
  ask BASIC_AUTH_USER "Username [officer]:"
  BASIC_AUTH_USER=${BASIC_AUTH_USER:-officer}
  [[ "$BASIC_AUTH_USER" =~ [[:space:]:] ]] || break
  warn "the username can't contain ':' or whitespace"
done
while :; do
  ask_secret BASIC_AUTH_PASSWORD "Password (min 12 chars):"
  (( ${#BASIC_AUTH_PASSWORD} >= 12 )) && break
  warn "at least 12 characters"
done
write_env BASIC_AUTH_USER "$BASIC_AUTH_USER"
write_env BASIC_AUTH_PASSWORD "$BASIC_AUTH_PASSWORD"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "AWS: SSH key + firewall"
key_new=0
if [[ ! -f "$SSH_KEY" ]]; then
  mkdir -p "$(dirname "$SSH_KEY")"
  ssh-keygen -q -t ed25519 -N '' -C tapat-deploy -f "$SSH_KEY"
  key_new=1
  say "Created $SSH_KEY"
fi
if aws ec2 describe-key-pairs --region "$R" --key-names "$KEY_PAIR_NAME" >/dev/null 2>&1; then
  if (( key_new )); then
    warn "EC2 key pair $KEY_PAIR_NAME exists but holds a different key than the one just created."
    note "An instance trusts only the key it was launched with: restore the old $SSH_KEY if tapat-api exists."
    confirm "Replace key pair $KEY_PAIR_NAME with the new key (fine when no tapat-api instance exists yet)?" || exit 1
    aws ec2 delete-key-pair --region "$R" --key-name "$KEY_PAIR_NAME" >/dev/null
    aws ec2 import-key-pair --region "$R" --key-name "$KEY_PAIR_NAME" \
      --public-key-material "fileb://$(winpath "$SSH_KEY.pub")" >/dev/null
    say "Replaced EC2 key pair $KEY_PAIR_NAME"
  fi
else
  aws ec2 import-key-pair --region "$R" --key-name "$KEY_PAIR_NAME" \
    --public-key-material "fileb://$(winpath "$SSH_KEY.pub")" >/dev/null
  say "Imported EC2 key pair $KEY_PAIR_NAME"
fi
VPC=$(awsq ec2 describe-vpcs --region "$R" --filters Name=is-default,Values=true --query 'Vpcs[0].VpcId')
if [[ "$VPC" == None ]]; then
  confirm "No default VPC in $R. Create one?" || exit 1
  aws ec2 create-default-vpc --region "$R" >/dev/null
  VPC=$(awsq ec2 describe-vpcs --region "$R" --filters Name=is-default,Values=true --query 'Vpcs[0].VpcId')
fi
AWS_SG_ID=$(awsq ec2 describe-security-groups --region "$R" \
  --filters "Name=group-name,Values=$SG_NAME" "Name=vpc-id,Values=$VPC" --query 'SecurityGroups[0].GroupId')
if [[ "$AWS_SG_ID" == None ]]; then
  AWS_SG_ID=$(awsq ec2 create-security-group --region "$R" --group-name "$SG_NAME" \
    --description "TAPat API: SSH only; Funnel is outbound" --vpc-id "$VPC" --query GroupId)
  say "Created security group $SG_NAME ($AWS_SG_ID)"
fi
MY_IP=$(curl -fsS --max-time 20 https://checkip.amazonaws.com | tr -d '\r\n ')
if ! out=$(aws ec2 authorize-security-group-ingress --region "$R" --group-id "$AWS_SG_ID" \
    --protocol tcp --port 22 --cidr "$MY_IP/32" 2>&1); then
  [[ "$out" == *InvalidPermission.Duplicate* ]] || { warn "$out"; exit 1; }
fi
# Revoke every other IPv4 tcp/22-22 rule, read from AWS (the git-ignored state file is not authoritative).
# The wizard only ever adds IPv4 tcp/22 rules; hand-added IPv6, UDP or port-range rules are not touched.
OTHER_CIDRS=$(awsq ec2 describe-security-groups --region "$R" --group-ids "$AWS_SG_ID" \
  --query 'SecurityGroups[0].IpPermissions[?IpProtocol==`tcp` && FromPort==`22` && ToPort==`22`].IpRanges[].CidrIp')
ssh_only=1
for cidr in $OTHER_CIDRS; do
  [[ "$cidr" == "$MY_IP/32" || "$cidr" == None ]] && continue
  if aws ec2 revoke-security-group-ingress --region "$R" --group-id "$AWS_SG_ID" \
      --protocol tcp --port 22 --cidr "$cidr" >/dev/null 2>&1; then
    say "Revoked the previous SSH source $cidr"
  else
    ssh_only=0
    fail_check ssh-ingress "could not revoke $cidr from $SG_NAME; remove it in the EC2 console"
  fi
done
if (( ssh_only )); then
  say "The wizard's SSH rule allows $MY_IP/32 only (tcp/22, IPv4). Funnel is outbound, so no other port is needed (deployment.md §3)."
fi
note "Rules added by hand outside this wizard (IPv6, port ranges) are left alone: check the group in the EC2 console."
note "New laptop IP (venue Wi-Fi)? Re-run the wizard; this stage swaps it in."
write_env AWS_SG_ID "$AWS_SG_ID"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "AWS: EC2 instance"
AWS_INSTANCE_ID=$(awsq ec2 describe-instances --region "$R" \
  --filters "Name=tag:Name,Values=$INSTANCE_TAG" Name=instance-state-name,Values=pending,running,stopping,stopped \
  --query 'Reservations[0].Instances[0].InstanceId')
if [[ "$AWS_INSTANCE_ID" != None ]]; then
  STATE=$(awsq ec2 describe-instances --region "$R" --instance-ids "$AWS_INSTANCE_ID" \
    --query 'Reservations[0].Instances[0].State.Name')
  say "Found $AWS_INSTANCE_ID ($STATE)."
  if [[ "$STATE" == stopping ]]; then
    aws ec2 wait instance-stopped --region "$R" --instance-ids "$AWS_INSTANCE_ID"
    STATE=stopped
  fi
  if [[ "$STATE" == stopped ]]; then
    aws ec2 start-instances --region "$R" --instance-ids "$AWS_INSTANCE_ID" >/dev/null
    say "Started $AWS_INSTANCE_ID."
  fi
else
  TYPES=$(awsq ec2 describe-instance-types --region "$R" \
    --filters Name=free-tier-eligible,Values=true --query 'InstanceTypes[].InstanceType')
  if grep -qwF t3.small <<<"$TYPES"; then TYPE=t3.small
  elif grep -qwF t3.micro <<<"$TYPES"; then TYPE=t3.micro
  else
    confirm "No free-tier type here. Launch t3.small (billed)?" || exit 1
    TYPE=t3.small
  fi
  AMI=$(awsq ssm get-parameter --region "$R" --name "$UBUNTU_AMI_PARAM" --query Parameter.Value)
  say "Ubuntu 24.04 · $TYPE · 30 GB gp3 · IMDSv2 only · termination protection (the disk holds SQLite)."
  confirm "Launch $TYPE ($AMI) in $R?" || exit 1
  AWS_INSTANCE_ID=$(awsq ec2 run-instances --region "$R" --image-id "$AMI" --instance-type "$TYPE" \
    --key-name "$KEY_PAIR_NAME" --security-group-ids "$AWS_SG_ID" \
    --block-device-mappings 'DeviceName=/dev/sda1,Ebs={VolumeSize=30,VolumeType=gp3}' \
    --metadata-options HttpTokens=required --disable-api-termination \
    --tag-specifications "ResourceType=instance,Tags=[{Key=Name,Value=$INSTANCE_TAG}]" \
    --query 'Instances[0].InstanceId')
  say "Launched $AWS_INSTANCE_ID."
fi
write_env AWS_INSTANCE_ID "$AWS_INSTANCE_ID"
say "Waiting for the instance status checks (2–5 min)…"
aws ec2 wait instance-status-ok --region "$R" --instance-ids "$AWS_INSTANCE_ID"
AWS_HOST=$(awsq ec2 describe-instances --region "$R" --instance-ids "$AWS_INSTANCE_ID" \
  --query 'Reservations[0].Instances[0].PublicIpAddress')
if [[ -z "$AWS_HOST" || "$AWS_HOST" == None ]]; then warn "$AWS_INSTANCE_ID has no public IPv4 address"; exit 1; fi
write_env AWS_HOST "$AWS_HOST"
note "No Elastic IP: the IP may change after a stop/start, so every run re-reads it. Only SSH uses it."
ssh_ok=0
for _ in $(seq 1 30); do
  if vm true 2>/dev/null; then ssh_ok=1; break; fi
  sleep 5
done
if (( ! ssh_ok )); then
  warn "SSH to $SSH_USER@$AWS_HOST never answered. Check: your IP vs the security group (re-run), and that"
  warn "$SSH_KEY is the key this instance was launched with."
  exit 1
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "VM: deploy key + provision"
say "$GITHUB_REPO is private: the VM's tapat user gets a read-only deploy key before"
say "provision.sh clones it (deployment.md §6.2 step 4)."
vm "id -u tapat >/dev/null 2>&1 || sudo useradd --system --create-home -U --shell /bin/bash tapat"
vm "sudo install -d -o tapat -g tapat -m 700 /home/tapat/.ssh"
vm "sudo -H -u tapat test -f /home/tapat/.ssh/id_ed25519 || sudo -H -u tapat ssh-keygen -q -t ed25519 -N '' -C tapat-ec2 -f /home/tapat/.ssh/id_ed25519"
vm "sudo -H -u tapat sh -c 'grep -q github.com ~/.ssh/known_hosts 2>/dev/null || ssh-keyscan -t ed25519 github.com >> ~/.ssh/known_hosts 2>/dev/null'"
PUB=$(vm "sudo cat /home/tapat/.ssh/id_ed25519.pub" | tr -d '\r')
KEYBODY=$(awk '{ print $1 " " $2 }' <<<"$PUB")
KEYS=$(gh repo deploy-key list -R "$GITHUB_REPO" --json key -q '.[].key' | tr -d '\r')
if grep -qF "$KEYBODY" <<<"$KEYS"; then
  say "The deploy key is already registered on $GITHUB_REPO."
else
  tmp=$(mktemp)
  printf '%s\n' "$PUB" > "$tmp"
  gh repo deploy-key add "$(winpath "$tmp")" -R "$GITHUB_REPO" -t "tapat-ec2-$AWS_INSTANCE_ID"
  rm -f "$tmp"
fi
# Ubuntu's bash rejects CRLF; a Windows checkout (core.autocrlf) has it, so strip it on the way up.
tr -d '\r' < deploy/provision.sh | vm "cat > /tmp/provision.sh"
say "Running provision.sh (apt, Node 22, pnpm, Caddy, Tailscale; 5–10 min)…"
if ! vm "sudo bash /tmp/provision.sh git@github.com:$GITHUB_REPO.git"; then
  warn "provision.sh failed: fix the error above, then re-run"
  exit 1
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Tailscale Funnel"
open_url "https://login.tailscale.com/admin/dns"
step "Enable MagicDNS and HTTPS Certificates for the tailnet (once per tailnet)."
pause "Done? Press Enter"
step "If the next command prints a login URL, open it and approve the machine."
vm_tty "sudo tailscale up --hostname=tapat"
step "If the next command prints a URL to enable Funnel, open it and enable Funnel; the command then continues."
if ! vm_tty "sudo tailscale funnel --bg 8080"; then
  pause "Enable Funnel at the URL above, then press Enter to retry"
  vm_tty "sudo tailscale funnel --bg 8080"
fi
FUNNEL_HOST=$(vm "sudo tailscale status --json | python3 -c 'import json,sys;print(json.load(sys.stdin)[\"Self\"][\"DNSName\"].rstrip(\".\"))'" | tr -d '\r')
if [[ -z "$FUNNEL_HOST" ]]; then warn "could not read the machine's tailnet hostname"; exit 1; fi
write_env FUNNEL_URL "https://$FUNNEL_HOST"
note "The hostname is tapat-1 (or similar) when 'tapat' is already taken in the tailnet."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Caddy basic auth"
# The password reaches caddy on stdin, never on a remote command line.
HASH=$(printf '%s\n' "$BASIC_AUTH_PASSWORD" | vm "caddy hash-password" | tr -d '\r')
if [[ "$HASH" != '$2'* ]]; then warn "caddy hash-password returned no bcrypt hash"; exit 1; fi
printf '%s %s\n' "$BASIC_AUTH_USER" "$HASH" | vm "sudo tee /etc/caddy/tapat-users >/dev/null"
# With `admin off`, only a restart re-reads the users file.
vm "sudo systemctl enable caddy && sudo systemctl restart caddy"
say "DEP1: $FUNNEL_URL/ must answer 401 (the first request may wait for the certificate)…"
code=000
for _ in $(seq 1 6); do
  code=$(http_code "$FUNNEL_URL/")
  [[ "$code" == 401 ]] && break
  sleep 5
done
if [[ "$code" == 401 ]]; then
  pass "DEP1: Funnel → Caddy asks for basic auth (401)"
else
  fail_check DEP1 "$FUNNEL_URL/ returned $code, expected 401"
  pause
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Prod .env"
say "The VM runs the PROD profile (GAS_MODE=velo, deployment.md §4). Point at Jim's prod .env;"
say "the wizard sets PUBLIC_BASE_URL in that file in place, then uploads it in stage 10."
while :; do
  ask PROD_ENV_PATH "Path to the PROD apps/server .env [apps/server/.env]:"
  PROD_ENV_PATH=${PROD_ENV_PATH:-apps/server/.env}
  if [[ ! -f "$PROD_ENV_PATH" ]]; then warn "no file at $PROD_ENV_PATH"; continue; fi
  grep -Eq "^GAS_MODE=['\"]?velo['\"]?[[:space:]]*$" "$PROD_ENV_PATH" && break
  warn "this is not the prod profile (GAS_MODE must be velo)"
done
write_env PROD_ENV_PATH "$PROD_ENV_PATH"
write_prod PUBLIC_BASE_URL "$FUNNEL_URL"
note "PUBLIC_BASE_URL stays the Funnel URL with Vercel on: webhooks and checkout redirects bypass Vercel (§9.1)."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Velo webhook"
open_url "https://velo-build.dev"
note "Dashboard labels unverified: follow what the dashboard shows."
step "Edit the existing webhook endpoint (create one if there is none)."
step "URL: $FUNNEL_URL/api/webhooks/velo"
step "Events: payment.succeeded, payment.failed, payment.created"
pause "Saved? Press Enter"
if confirm "Did Velo show a NEW signing secret?"; then
  # "Enter keeps current" must offer the prod file's value, so ask against it.
  ENV_FILE="$PROD_ENV_PATH"
  ask_secret VELO_WEBHOOK_SECRET "Paste the signing secret:"
  ENV_FILE="$STATE_FILE"
  write_prod VELO_WEBHOOK_SECRET "$VELO_WEBHOOK_SECRET"
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Cut-over: upload .env, build, start"
warn "Only one API may run with the prod .env (deployment.md §4)."
confirm "Every other API using the prod .env is stopped (laptop, any Oracle/GCP VM)? Telegram 409s and Stellar sequence races otherwise." || exit 1
# Streamed into a 600 temp file: the secrets never sit world-readable in /tmp.
vm "umask 077 && cat > /tmp/api.env" < "$PROD_ENV_PATH"
vm "sudo install -o tapat -g tapat -m 600 /tmp/api.env /opt/tapat/apps/server/.env && rm -f /tmp/api.env"
# The VM's tapat-web stays the fallback at the Funnel URL (deployment.md §9.3, §10).
printf 'API_ORIGIN=http://127.0.0.1:4000\n' | vm "sudo -H -u tapat tee /opt/tapat/apps/web/.env.local >/dev/null"
say "Pull, install, build, (re)start (3–6 min)…"
vm "sudo -H -u tapat git -C /opt/tapat pull --ff-only && sudo -H -u tapat pnpm -C /opt/tapat install --frozen-lockfile && sudo -H -u tapat pnpm -C /opt/tapat --filter web build && sudo install -d -o tapat -g tapat /opt/tapat/apps/server/data && sudo systemctl enable tapat-api tapat-web && sudo systemctl restart tapat-api tapat-web"
say "Waiting for the API behind $FUNNEL_URL/api/health…"
code=000
for _ in $(seq 1 24); do
  code=$(http_code "$FUNNEL_URL/api/health")
  [[ "$code" != 502 && "$code" != 000 ]] && break
  sleep 5
done
if [[ "$code" != 502 && "$code" != 000 ]]; then
  pass "The API answers through Funnel → Caddy (HTTP $code)"
else
  vm "sudo journalctl -u tapat-api -n 40 --no-pager" || true
  fail_check API-start "see journal above"
  note "Config errors name the variable, never its value."
  pause
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Vercel: import project"
open_url "https://vercel.com/new"
note "Dashboard labels unverified: follow what Vercel shows."
step "Import $GITHUB_REPO (adjust the GitHub App's repository access if it isn't listed)."
step "Root Directory: apps/web · Framework: Next.js · Production branch: main."
step "Environment Variables, for Production and Preview:"
say "    API_ORIGIN     = $FUNNEL_URL"
say "    WEB_BASIC_AUTH = <user>:<password>, copied now:"
copy_clip "$BASIC_AUTH_USER:$BASIC_AUTH_PASSWORD"
step "Deploy."
note "Project already exists? Settings → Environment Variables: set both for Production and Preview, then Redeploy."
while :; do
  ask VERCEL_URL "Production URL (https://<project>.vercel.app):"
  VERCEL_URL=${VERCEL_URL%/}
  [[ "$VERCEL_URL" == https://* ]] && break
  warn "it must start with https://"
done
write_env VERCEL_URL "$VERCEL_URL"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Vercel: deployment protection off"
open_url "https://vercel.com/dashboard"
step "Project → Settings → Deployment Protection → Vercel Authentication: Disabled → Save."
note "The middleware's basic auth is the protection; teammates can't log in to a Hobby account (deployment.md §9.1)."
pause "Done? Press Enter"

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Verify"
AUTH="$BASIC_AUTH_USER:$BASIC_AUTH_PASSWORD"
code=$(http_code "$FUNNEL_URL/")
if [[ "$code" == 401 ]]; then pass "Funnel /: Caddy asks for basic auth (401)"
else fail_check funnel-auth "$FUNNEL_URL/ returned $code, expected 401"; fi
body=$(curl -s --max-time 20 "$FUNNEL_URL/api/health" || true)
if [[ "$body" == *'"ok":true'* || "$body" == *'"NOT_FOUND"'* ]]; then pass "Funnel /api/health: no password needed, the API answers"
else fail_check funnel-health "$FUNNEL_URL/api/health body: ${body:0:120}"; fi
code=$(http_code "$FUNNEL_URL/" -u "$AUTH")
if [[ "$code" == 200 ]]; then pass "Funnel / with the password: the VM's web fallback (200)"
else fail_check funnel-web "$FUNNEL_URL/ with the password returned $code, expected 200"; fi
code=$(http_code "$VERCEL_URL/")
if [[ "$code" == 401 ]]; then pass "Vercel /: the middleware asks for basic auth (401)"
else fail_check vercel-auth "$VERCEL_URL/ returned $code, expected 401"; fi
code=$(http_code "$VERCEL_URL/" -u "$AUTH")
if [[ "$code" == 200 ]]; then pass "Vercel / with the password (200)"
else fail_check vercel-web "$VERCEL_URL/ with the password returned $code, expected 200"; fi
resp=$(curl -s --max-time 20 -u "$AUTH" -w '\n%{http_code}' "$VERCEL_URL/api/wizard-probe" || true)
code=${resp##*$'\n'}
body=${resp%$'\n'*}
if [[ "$body" == *'"NOT_FOUND"'* ]]; then
  pass "Vercel /api/*: Vercel → Funnel → Caddy → Fastify, Authorization forwarded"
elif [[ "$code" == 401 ]]; then
  fail_check vercel-auth-forward "Vercel did not forward Authorization; apply deployment.md §9.1 x-origin-secret fallback (Caddyfile change, Jim)"
else
  fail_check vercel-api "$VERCEL_URL/api/wizard-probe returned $code: ${body:0:120}"
fi
printf '\n'
say "Still by hand (deployment.md §9.4):"
step "The phone reads a tag on $VERCEL_URL/station/A."
step "/api/stream through Vercel stays connected > 5 min (the dashboard at $VERCEL_URL/ keeps updating)."
step "Velo dashboard → send test to $FUNNEL_URL/api/webhooks/velo returns 200."
step "Switch the laptop's apps/server/.env back to the dev profile (deployment.md §4)."
pause "Press Enter for the summary"

finish
note "wrote ${#PROD_WRITTEN[@]} value(s) to $PROD_ENV_PATH: ${PROD_WRITTEN[*]}"
note "API (Funnel): $FUNNEL_URL"
note "Web (Vercel): $VERCEL_URL"
printf '\n'
}

run_wizard "$@"; exit
